import { readdirSync, statSync } from 'node:fs';
import path from 'node:path';
/**
 * Recursively validates the total size of a folder, including all nested files and subdirectories.
 */
export function isFolderLargerThan(folder, maxBytes) {
    if (!statSync(folder).isDirectory()) {
        throw new Error('Provided path is not a directory');
    }
    function recurse(f, bytesSoFar) {
        let totalBytes = bytesSoFar;
        const fileEntries = readdirSync(f);
        for (const file of fileEntries) {
            const filePath = path.join(f.toString(), file);
            const stats = statSync(filePath);
            if (stats.isFile()) {
                totalBytes += stats.size;
            }
            else if (stats.isDirectory()) {
                const result = recurse(filePath, totalBytes);
                totalBytes = result.totalBytes;
            }
            // return early if we have already exceeded the maximum
            if (totalBytes > maxBytes) {
                return {
                    totalBytes,
                    exceededMax: true,
                };
            }
        }
        return {
            totalBytes,
            exceededMax: false,
        };
    }
    const result = recurse(folder, 0);
    return result.exceededMax;
}
